# Terraform Module: S3 + RDS + IRSA Role

```
.
├── modules/
│   ├── s3-bucket/
│   ├── rds-postgres/
│   └── irsa-role/
├── envs/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── backend.tf
└── versions.tf
```

---

## versions.tf

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}
```

## backend.tf

```hcl
terraform {
  backend "s3" {
    key    = "app/terraform.tfstate"
    # bucket & dynamodb_table passed via -backend-config per env
  }
}
```

## modules/s3-bucket/main.tf

```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.use_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.use_kms ? aws_kms_key.this[0].arn : null
    }
    bucket_key_enabled = var.use_kms
  }
}

resource "aws_kms_key" "this" {
  count                   = var.use_kms ? 1 : 0
  description             = "KMS key for ${var.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.replication_bucket_arn != null ? 1 : 0
  role  = aws_iam_role.replication[0].arn
  bucket = aws_s3_bucket.this.id

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = var.replication_bucket_arn
      storage_class = "STANDARD_IA"
    }
  }
  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_iam_role" "replication" {
  count = var.replication_bucket_arn != null ? 1 : 0
  name  = "${var.bucket_name}-replication"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_bucket_arn != null ? 1 : 0
  name  = "replication"
  role  = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Effect = "Allow"
        Action = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = ["${var.replication_bucket_arn}/*"]
      }
    ]
  })
}
```

## modules/s3-bucket/variables.tf & outputs.tf

```hcl
variable "bucket_name" { type = string }
variable "use_kms" { type = bool, default = false }
variable "replication_bucket_arn" { type = string, default = null }
variable "tags" { type = map(string), default = {} }

output "bucket_arn" { value = aws_s3_bucket.this.arn }
output "bucket_name" { value = aws_s3_bucket.this.id }
```

## modules/rds-postgres/main.tf

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.name}-db-subnets"
  subnet_ids = var.subnet_ids
}

resource "aws_security_group" "this" {
  name   = "${var.name}-db"
  vpc_id = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_groups
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "random_password" "master" {
  length  = 32
  special = false
}

resource "aws_db_instance" "this" {
  identifier     = var.name
  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.max_allocated_storage
  storage_encrypted     = true

  db_name  = var.db_name
  username = var.username
  password = var.master_password != null ? var.master_password : random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.this.id]

  multi_az                   = var.multi_az
  publicly_accessible        = false
  deletion_protection        = true # acceptance criterion: always on
  backup_retention_period    = max(var.backup_retention_days, 7)
  skip_final_snapshot        = false
  final_snapshot_identifier  = "${var.name}-final"
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  tags = var.tags
}
```

## modules/rds-postgres/variables.tf & outputs.tf

```hcl
variable "name" { type = string }
variable "vpc_id" { type = string }
variable "subnet_ids" { type = list(string) }
variable "allowed_security_groups" { type = list(string), default = [] }
variable "instance_class" { type = string }
variable "engine_version" { type = string, default = "15.5" }
variable "allocated_storage" { type = number, default = 20 }
variable "max_allocated_storage" { type = number, default = 100 }
variable "multi_az" { type = bool, default = false }
variable "backup_retention_days" { type = number, default = 7 }
variable "db_name" { type = string, default = "appdb" }
variable "username" { type = string, default = "appuser" }
variable "master_password" { type = string, default = null, sensitive = true }
variable "tags" { type = map(string), default = {} }

output "endpoint" {
  value     = aws_db_instance.this.endpoint
  sensitive = false
}

output "master_password" {
  value     = var.master_password != null ? null : random_password.master.result
  sensitive = true
}

output "db_arn" { value = aws_db_instance.this.arn }
```

## modules/irsa-role/main.tf — OIDC trust, least privilege

```hcl
data "aws_iam_policy_document" "trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_host}:sub"
      values   = ["system:serviceaccount:${var.k8s_namespace}:${var.service_account}"]
    }
  }
}

resource "aws_iam_role" "this" {
  name               = var.name
  assume_role_policy = data.aws_iam_policy_document.trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "least_privilege" {
  name = "${var.name}-s3-access"
  role = aws_iam_role.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BucketList"
        Effect = "Allow"
        Action = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [var.bucket_arn]
      },
      {
        Sid    = "ObjectAccess"
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
        Resource = ["${var.bucket_arn}/*"]
      }
      # No wildcards; scoped to this bucket only
    ]
  })
}
```

```hcl
variable "name" { type = string }
variable "oidc_provider_arn" { type = string }
variable "oidc_provider_host" { type = string }
variable "k8s_namespace" { type = string }
variable "service_account" { type = string }
variable "bucket_arn" { type = string }
variable "tags" { type = map(string), default = {} }

output "role_arn" { value = aws_iam_role.this.arn }
```

