## Root composition — main.tf

```hcl
locals {
  env   = var.environment
  name  = "app-${local.env}"
  tags  = merge(var.tags, { Environment = local.env, ManagedBy = "terraform" })
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "db" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

module "assets_bucket" {
  source = "./modules/s3-bucket"

  bucket_name           = "${local.name}-assets"
  use_kms               = var.bucket_use_kms
  replication_bucket_arn = var.bucket_replication_target_arn
  tags                  = local.tags
}

module "db" {
  source = "./modules/rds-postgres"

  name                   = local.name
  vpc_id                 = data.aws_vpc.default.id
  subnet_ids             = data.aws_subnets.db.ids
  instance_class         = var.db_instance_class
  multi_az               = var.db_multi_az
  master_password        = var.db_master_password # supply via env var / sops; never commit
  tags                   = local.tags
}

module "app_role" {
  source = "./modules/irsa-role"

  name               = "${local.name}-sa-role"
  oidc_provider_arn  = var.oidc_provider_arn
  oidc_provider_host = var.oidc_provider_host
  k8s_namespace      = var.k8s_namespace
  service_account    = var.k8s_service_account
  bucket_arn         = module.assets_bucket.bucket_arn
  tags               = local.tags
}
```

## variables.tf

```hcl
variable "environment" { type = string }
variable "aws_region" { type = string }

variable "db_instance_class" { type = string }
variable "db_multi_az" { type = bool, default = false }
variable "db_master_password" { type = string, sensitive = true, default = null }

variable "bucket_use_kms" { type = bool, default = false }
variable "bucket_replication_target_arn" { type = string, default = null }

variable "oidc_provider_arn" { type = string }
variable "oidc_provider_host" { type = string }
variable "k8s_namespace" { type = string, default = "app" }
variable "k8s_service_account" { type = string, default = "app-sa" }

variable "tags" { type = map(string), default = {} }
```

## outputs.tf

```hcl
output "bucket_name" { value = module.assets_bucket.bucket_name }
output "db_endpoint" { value = module.db.endpoint }
output "db_master_password" {
  value     = module.db.master_password
  sensitive = true
}
output "service_account_role_arn" { value = module.app_role.role_arn }

# EKS annotation: service-account.beta.kubernetes.io/role-arn: <service_account_role_arn>
```

---

## envs/dev.tfvars

```hcl
environment = "dev"
aws_region  = "us-east-1"

db_instance_class = "db.t3.micro"
db_multi_az       = false

bucket_use_kms = false
```

## envs/prod.tfvars

```hcl
environment = "prod"
aws_region  = "us-east-1"

db_instance_class = "db.t3.medium"
db_multi_az       = true

bucket_use_kms                = true
bucket_replication_target_arn = "arn:aws:s3:::app-prod-assets-dr" # in us-west-2

oidc_provider_arn  = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
oidc_provider_host = "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
```

## Usage

```bash
# Init with per-env remote state (isolation)
terraform init -backend-config="bucket=tfstate-prod" -backend-config="region=us-east-1"

# Deploy prod
terraform apply -var-file=envs/prod.tfvars

# Deploy dev — separate state file, independent
terraform init -backend-config="bucket=tfstate-dev" -backend-config="key=app-dev.tfstate"
terraform apply -var-file=envs/dev.tfvars
```

Secrets: pass `db_master_password` via `TF_VAR_db_master_password` from a secrets manager, or decrypt tfvars with SOPS:

```hcl
data "sops_file" "secrets" {
  source_file = "secrets/${var.environment}.enc.yaml"
}
```

## Acceptance criteria mapping

| Criterion | Implementation |
|---|---|
| Versioning + encryption, no public access | `aws_s3_bucket_versioning` + SSE config + `public_access_block` (all four flags) |
| Deletion protection, backups ≥7, not public | `deletion_protection = true`, `max(retention, 7)`, `publicly_accessible = false` |
| Secret not in plaintext | sensitive vars via env/SOPS; random_password fallback; no plaintext in git |
| Least privilege | IAM policy scoped to single bucket ARN, OIDC trust conditioned on service account |
| Env isolation | Separate state backends + tfvars per env; prod changes can't touch dev state |
| Prod KMS + replication | `use_kms` + `replication_bucket_arn` in prod.tfvars only |
